let latencyData = [];
        let isProcessing = false;
        window.addEventListener('keydown', (e) => {
            // Avoid repeat events when holding key
            if (e.repeat || isProcessing) return;
            const t1 = performance.now();
            isProcessing = true;
            // Use requestAnimationFrame to measure until next render
            requestAnimationFrame((t2) => {
                const latency = t2 - t1;
                recordHit(e.key.toUpperCase(), latency);
                isProcessing = false;
            });
        });
        function recordHit(key, latency) {
            const rounded = latency.toFixed(2);
            latencyData.push(parseFloat(rounded));
            // UI Updates
            document.getElementById('current-ms').innerText = rounded;
            const visualBox = document.getElementById('visual-trigger');
            visualBox.classList.remove('flash-active');
            void visualBox.offsetWidth; // Trigger reflow
            visualBox.classList.add('flash-active');
            updateStats();
            updateLog(key, rounded);
        }
        function updateStats() {
            const count = latencyData.length;
            if (count === 0) return;
            const min = Math.min(...latencyData);
            const max = Math.max(...latencyData);
            const avg = latencyData.reduce((a, b) => a + b, 0) / count;
            document.getElementById('stat-count').innerText = count;
            document.getElementById('stat-min').innerText = min.toFixed(1);
            document.getElementById('stat-max').innerText = max.toFixed(1);
            document.getElementById('stat-avg').innerText = avg.toFixed(1);
        }
        function updateLog(key, latency) {
            const body = document.getElementById('log-body');
            const time = new Date().toLocaleTimeString().split(' ')[0];
            // Remove placeholder
            if (latencyData.length === 1) body.innerHTML = '';
            const row = document.createElement('tr');
            row.className = "hover:bg-lime-50 transition-colors animate-fadeIn";
            row.innerHTML = `
                <td class="px-6 py-4 font-black text-slate-800">${key === ' ' ? '[SPACE]' : key}</td>
                <td class="px-6 py-4 font-mono font-bold text-lime-600">${latency}ms</td>
                <td class="px-6 py-4 text-right text-slate-400 font-mono">${time}</td>
            `;
            body.prepend(row);
            // Limit rows for performance
            if (body.children.length > 50) {
                body.lastElementChild.remove();
            }
        }
        function resetStats() {
            if (!confirm("Purge current buffer?")) return;
            latencyData = [];
            document.getElementById('log-body').innerHTML = '<tr><td colspan="3" class="px-6 py-12 text-center text-slate-300 font-black uppercase tracking-widest italic">Awaiting hardware signal...</td></tr>';
            document.getElementById('current-ms').innerText = "0.00";
            document.getElementById('stat-count').innerText = "0";
            document.getElementById('stat-min').innerText = "0.0";
            document.getElementById('stat-max').innerText = "0.0";
            document.getElementById('stat-avg').innerText = "0.0";
            showToast("Diagnostic buffer cleared.");
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-bounce font-black text-xs uppercase tracking-widest";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 4000);
        }
